// Native query/scan baselines for bench.py. Input files are generated by the harness.
#include <zstd.h>

#include <algorithm>
#include <charconv>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <limits>
#include <map>
#include <memory>
#include <stdexcept>
#include <string>
#include <string_view>
#include <vector>

using u64 = std::uint64_t;

static void check_zstd(std::size_t result) {
    if (ZSTD_isError(result))
        throw std::runtime_error(ZSTD_getErrorName(result));
}

static u64 load_u64(std::istream& file) {
    unsigned char bytes[8];
    if (!file.read(reinterpret_cast<char*>(bytes), 8))
        throw std::runtime_error("truncated index");
    u64 value = 0;
    for (int i = 7; i >= 0; --i)
        value = (value << 8) | bytes[i];
    return value;
}

static u64 read_varint(std::string_view& src) {
    u64 value = 0;
    for (unsigned shift = 0; shift < 64 && !src.empty(); shift += 7) {
        unsigned char next = src.front();
        src.remove_prefix(1);
        if (shift == 63 && next > 1) break;
        value |= u64(next & 127) << shift;
        if (next < 128) return value;
    }
    throw std::runtime_error("invalid integer in delta frame");
}

struct Output {
    bool scan;
    std::ostream& stream;
    std::map<u64, std::vector<std::size_t>> wanted;
    std::vector<std::string> matches;
    std::vector<std::uint32_t> original;
    decltype(wanted)::const_iterator current;
    Output(std::ostream& stream, const std::vector<u64>& ids, bool scan)
        : scan(scan), stream(stream), matches(ids.size()) {
        for (std::size_t i = 0; i < ids.size(); ++i) wanted[ids[i]].push_back(i);
        current = wanted.begin();
    }
    void apply_permutation(std::istream& in, u64 nrows) {
        std::map<u64, std::vector<std::size_t>> positions;
        auto integer = [](const unsigned char* p) {
            return std::uint32_t(p[0]) | std::uint32_t(p[1]) << 8 |
                   std::uint32_t(p[2]) << 16 | std::uint32_t(p[3]) << 24;
        };
        if (scan) {
            original.resize(nrows);
            matches.resize(nrows);
            std::vector<unsigned char> table(nrows * 4);
            if (!in.read(reinterpret_cast<char*>(table.data()), table.size()))
                throw std::runtime_error("truncated permutation");
            for (u64 id = 0; id < nrows; ++id) {
                auto physical = integer(&table[id * 4]);
                if (physical >= nrows) throw std::runtime_error("invalid permutation");
                original[physical] = static_cast<std::uint32_t>(id);
            }
        } else {
            auto begin = in.tellg();
            for (auto& entry : wanted) {
                unsigned char bytes[4];
                if (entry.first >= nrows) throw std::runtime_error("row outside archive");
                in.seekg(begin + std::streamoff(entry.first * 4));
                if (!in.read(reinterpret_cast<char*>(bytes), 4))
                    throw std::runtime_error("truncated permutation");
                positions.emplace(integer(bytes), std::move(entry.second));
            }
            wanted = std::move(positions);
            current = wanted.begin();
        }
    }
    void row(u64 id, std::string_view data) {
        if (!original.empty()) { matches[original[id]].assign(data); return; }
        if (scan) { stream << data << '\n'; return; }
        if (current != wanted.end() && current->first == id) {
            for (auto index : current->second) matches[index].assign(data);
            ++current;
        }
    }
    bool needed(u64 id) const { return scan || (current != wanted.end() && current->first == id); }
    void finish() {
        for (const auto& line : matches) {
            if (line.empty()) throw std::runtime_error("missing requested row");
            stream << line << '\n';
        }
        stream.flush();
        if (!stream) throw std::runtime_error("output write failed");
    }
};

static std::string read_frame(std::istream& file, ZSTD_DCtx* dctx, u64 start, u64 end) {
    if (start > end) throw std::runtime_error("invalid frame offset");
    file.seekg(start);
    std::string compressed(end - start, '\0');
    if (!file.read(compressed.data(), compressed.size()))
        throw std::runtime_error("truncated frame");
    auto size = ZSTD_getFrameContentSize(compressed.data(), compressed.size());
    if (size == ZSTD_CONTENTSIZE_ERROR || size == ZSTD_CONTENTSIZE_UNKNOWN)
        throw std::runtime_error("invalid frame header");
    std::string data(size, '\0');
    check_zstd(ZSTD_decompressDCtx(dctx, data.data(), data.size(), compressed.data(), compressed.size()));
    return data;
}

static void raw_rows(std::string_view data, u64 begin, u64 last, Output& out) {
    for (u64 row = begin; row <= last; ++row) {
        auto nl = data.find('\n');
        if (nl == data.npos) throw std::runtime_error("truncated JSONL frame");
        out.row(row, data.substr(0, nl));
        data.remove_prefix(nl + 1);
    }
}

static void delta_rows(std::string_view data, u64 begin, u64 last, Output& out, bool runs) {
    std::string record;
    std::vector<u64> prefix;
    for (u64 row = begin; row <= last; ++row) {
        u64 bytes = read_varint(data);
        if (bytes > data.size()) throw std::runtime_error("truncated metadata");
        auto metadata = data.substr(0, bytes);
        data.remove_prefix(bytes);
        u64 retained = read_varint(data), appended = read_varint(data);
        if (retained > prefix.size()) throw std::runtime_error("invalid prefix length");
        prefix.resize(retained);
        while (appended) {
            u64 count = appended;
            bool sequence = false;
            if (runs) {
                u64 header = read_varint(data);
                count = header >> 1;
                sequence = header & 1;
                if (!count || count > appended) throw std::runtime_error("invalid run size");
            }
            u64 base = sequence ? read_varint(data) : 0;
            for (u64 j = 0; j < count; ++j)
                prefix.push_back(sequence ? base + j : read_varint(data));
            appended -= count;
        }
        if (out.needed(row)) {
            record.assign(metadata);
            if (metadata.size() > 1) record += ',';
            record += "\"hash_ids\":[";
            for (std::size_t i = 0; i < prefix.size(); ++i) {
                if (i) record += ',';
                char buf[32];
                auto result = std::to_chars(buf, buf + sizeof(buf), prefix[i]);
                record.append(buf, result.ptr);
            }
            record += "]}";
            out.row(row, record);
        }
    }
}

static void indexed(std::istream& in, Output& out, bool delta, bool sorted, bool runs) {
    if (load_u64(in) != 1) throw std::runtime_error("unexpected index version");
    const auto nrows = load_u64(in), nper = load_u64(in);
    if (nper == 0) throw std::runtime_error("invalid frame size");
    const auto nframes = nrows / nper + (nrows % nper != 0);
    std::vector<u64> offsets(nframes + 1);
    for (auto& offset : offsets) offset = load_u64(in);
    if (sorted) out.apply_permutation(in, nrows);
    std::map<u64, u64> last_wanted;
    for (const auto& entry : out.wanted) {
        if (entry.first >= nrows) throw std::runtime_error("row outside archive");
        last_wanted[entry.first / nper] = entry.first;
    }
    std::unique_ptr<ZSTD_DCtx, decltype(&ZSTD_freeDCtx)> dctx(ZSTD_createDCtx(), ZSTD_freeDCtx);
    if (!dctx) throw std::bad_alloc();
    auto process = [&](u64 frame, u64 last) {
        auto raw = read_frame(in, dctx.get(), offsets[frame], offsets[frame + 1]);
        if (out.scan && !delta && !sorted) {
            out.stream << raw;
            return;
        }
        if (delta) delta_rows(raw, frame * nper, last, out, runs);
        else raw_rows(raw, frame * nper, last, out);
    };
    if (out.scan) {
        for (u64 i = 0; i < nframes; ++i) process(i, std::min((i + 1) * nper, nrows) - 1);
    } else {
        for (const auto& [frame, last] : last_wanted) process(frame, last);
    }
}

// Streaming whole-file reader stops once all requested rows have arrived.
static void whole(std::istream& in, Output& out) {
    auto stream = ZSTD_createDStream();
    if (!stream) throw std::bad_alloc();
    check_zstd(ZSTD_initDStream(stream));
    std::vector<char> src(ZSTD_DStreamInSize()), dst(ZSTD_DStreamOutSize());
    std::string carry;
    u64 row = 0, last = out.scan ? std::numeric_limits<u64>::max() : out.wanted.rbegin()->first;
    std::size_t remaining = 1;
    while (row <= last && in) {
        in.read(src.data(), src.size());
        ZSTD_inBuffer input{src.data(), static_cast<std::size_t>(in.gcount()), 0};
        while (input.pos < input.size && row <= last) {
            ZSTD_outBuffer output{dst.data(), dst.size(), 0};
            remaining = ZSTD_decompressStream(stream, &output, &input);
            check_zstd(remaining);
            if (out.scan) { out.stream.write(dst.data(), output.pos); continue; }
            std::string_view data(dst.data(), output.pos);
            while (!data.empty() && row <= last) {
                auto nl = data.find('\n');
                if (nl == data.npos) { carry.append(data); break; }
                if (carry.empty()) out.row(row, data.substr(0, nl));
                else {
                    carry.append(data.substr(0, nl));
                    out.row(row, carry); carry.clear();
                }
                data.remove_prefix(nl + 1);
                ++row;
            }
        }
    }
    ZSTD_freeDStream(stream);
    if (row <= last && remaining) throw std::runtime_error("truncated whole-file archive");
}

int main(int argc, char** argv) {
    try {
        if (argc < 5) throw std::runtime_error("usage: reader whole|frame|delta|sorted get|scan archive argument...");
        const std::string mode(argv[1]), op(argv[2]);
        bool scan = op == "scan";
        std::ifstream file(argv[3], std::ios::binary);
        if (!file) throw std::runtime_error("cannot open archive");
        std::ofstream output;
        std::vector<u64> ids;
        if (scan) {
            output.open(argv[4], std::ios::binary);
            if (!output) throw std::runtime_error("cannot create output");
        } else if (op == "get") {
            for (int i = 4; i < argc; ++i) ids.push_back(std::stoull(argv[i]));
        } else throw std::runtime_error("unknown operation");
        std::ios_base::sync_with_stdio(false);
        Output out(scan ? static_cast<std::ostream&>(output) : std::cout, ids, scan);
        if (mode == "whole") whole(file, out);
        else if (mode == "frame" || mode == "delta" || mode == "sorted" ||
                 mode == "runs" || mode == "sorted_runs") {
            bool runs = mode == "runs" || mode == "sorted_runs";
            indexed(file, out, mode == "delta" || runs, mode == "sorted" || mode == "sorted_runs", runs);
        }
        else throw std::runtime_error("unknown codec");
        out.finish();
        return 0;
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n'; return 1;
    }
}
